module top_module(
  input clk,
  input reset,
  input [1:0] product_id,
  input [5:0] money_inserted,
  output reg dispense,
  output reg [5:0] change,
  output reg [1:0] product_dispensed
);// Define the prices of each product
  parameter PRICE_00 = 50;
  parameter PRICE_01 = 75;
  parameter PRICE_10 = 100;
  parameter PRICE_11 = 125;

  // Define the state machine states
  parameter IDLE = 2'b00;
  parameter WAIT_FOR_MONEY = 2'b01;
  parameter DISPENSE_PRODUCT = 2'b10;

  // Define the state machine signals
  reg [1:0] state;
  reg [5:0] current_money;
  reg [5:0] product_price;

  // Initialize the state machine
  always @(posedge clk, posedge reset) begin
    if (reset) begin
      state <= IDLE;
      current_money <= 0;
      product_price <= 0;
      dispense <= 0;
      change <= 0;
      product_dispensed <= 0;
    end else begin
      case(state)
        IDLE: begin
          // Wait for the user to select a product
          product_dispensed <= 0;
          product_price <= 0;
          if (product_id != 0) begin
            // Set the price of the selected product
            case(product_id)
              1: product_price <= PRICE_01;
              2: product_price <= PRICE_10;
              3: product_price <= PRICE_11;
            endcase
            state <= WAIT_FOR_MONEY;
          end
        end
        WAIT_FOR_MONEY: begin
          // Wait for the user to insert enough money
          if (money_inserted >= product_price) begin
            current_money <= money_inserted;
            state <= DISPENSE_PRODUCT;
          end
        end
        DISPENSE_PRODUCT: begin
          // Dispense the product and return change
          dispense <= 1;
          product_dispensed <= product_id;
          change <= current_money - product_price;
          current_money <= 0;
          state <= IDLE;
        end
      endcase
    end
  end

endmodule

