description:
Design a state machine for a simple game that tracks the health of a boss and a player. The module outputs a 2-bit game state: it resets to '00' upon receiving a reset signal, transitions to '01' when the boss's health reaches zero, and transitions to '10' when the player's health reaches zero. If neither condition is met, it defaults back to '00'. This functionality allows for monitoring the game's status based on player and boss health levels.
module top_module(clk, rst, bossHP, playerHP, gameState
    );

code:
module top_module(clk, rst, bossHP, playerHP, gameState
    );input clk, rst;
	input [9:0] bossHP;
	input [1:0] playerHP;
	output reg [1:0] gameState;

	always @ (posedge clk) begin
		if (rst)
			gameState <= 2'b00;
		else if (bossHP <= 0)
			gameState <= 2'b01;
		else if (playerHP <= 0)
			gameState <= 2'b10;
		else
			gameState <= 2'b00;
	end


endmodule

