module top_module(
    input clk,
    input load,
    input [3:0] data_in,
    input shift,
    output [3:0] data_out
);reg [3:0] shift_reg;

always @(posedge clk) begin
    if (load) begin
        shift_reg <= data_in;
    end else if (shift) begin
        shift_reg <= {shift_reg[2:0], 1'b0};
    end
end

assign data_out = shift_reg;

endmodule

