module digital_lock (
  input correct_code,
  input incorrect_code,
  input [1:0] state,
  output reg [1:0] next_state,
  output reg [1:0] status);parameter LOCKED=0, UNLOCKED=1, ALARM=2;

    always_comb begin
        case (state)
            LOCKED: next_state = correct_code ? UNLOCKED : (incorrect_code ? ALARM : LOCKED);
            UNLOCKED: next_state = LOCKED;
            ALARM: next_state = LOCKED;
        endcase
    end

    always_comb begin
        case (state)
            LOCKED: status = 2'b00;
            UNLOCKED: status = 2'b01;
            ALARM: status = 2'b10;
        endcase
    end

endmodule

