description:
Design a control unit for an ALU (Arithmetic Logic Unit) that generates a 3-bit output control signal based on the operation type specified by the inputs. The module takes a 6-bit function code (`funct_i`) and a 2-bit ALU operation code (`aluop_i`) as inputs. Depending on the value of `aluop_i`, it outputs a certain control signal: a default encoding for two basic operations when `aluop_i` is `00`, and specific encodings for different ALU operations (like addition, subtraction, and logical operations) based on the value of `funct_i`. The output controls the operation performed by the ALU.
module top_module(
	funct_i,
	aluop_i,
	aluctrl_o
);

code:
module top_module(
	funct_i,
	aluop_i,
	aluctrl_o
);input 	[5:0] 	funct_i;
input 	[1:0] 	aluop_i;
output 	[2:0] 	aluctrl_o;

reg 	[2:0] 	temp_aluctrl_o;
assign aluctrl_o = temp_aluctrl_o;

always @ (funct_i or aluop_i)
begin
	if (aluop_i == 2'b00)
		temp_aluctrl_o = 3'b001;
	else
		case (funct_i)
			6'b100000: temp_aluctrl_o = 3'b001;
			6'b100010: temp_aluctrl_o = 3'b010;
			6'b100100: temp_aluctrl_o = 3'b011;
			6'b100101: temp_aluctrl_o = 3'b100;
			6'b011000: temp_aluctrl_o = 3'b101;
			default: temp_aluctrl_o = 3'b000;
		endcase
end


endmodule

