);

code:
module top_module(
  input in,
  input clk,
  output reg out
);parameter d = 10; // number of clock cycles of delay

reg [d-1:0] delay_buffer;

always @(posedge clk) begin
  delay_buffer <= {delay_buffer[d-2:0], in};
  out <= delay_buffer[d-1];
end

endmodule

