module dual_port_ram(
    input               clk     , 
    input               rstn    ,
    input               wr_en   ,
    input       [5:0]   rd_addr ,
    input       [5:0]   wr_addr ,
    input       [7:0]   data_in ,

    output reg  [7:0]   data_out
);

reg [7:0] mem [63:0];

// Write operation
always @(posedge clk or negedge rstn) begin
    if (!rstn) begin
        integer i;
        for (i = 0; i < 64; i = i + 1) begin
            mem[i] <= 0;
        end
    end else if (wr_en) begin
        mem[wr_addr] <= data_in;
    end
end

// Read operation
always @(posedge clk or negedge rstn) begin
    if (!rstn) begin
        data_out <= 0;
    end else begin
        data_out <= mem[rd_addr];
    end
end

endmodule

