Implement the Verilog module based on the following description.
Module G implements the boolean function v = ~(x & y).

// Module H can be described by the following simulation waveform: 

If x = 1, y = 1, then v = 0.
If x = 0, y = 1, then v = 1.
If x = 0, y = 0, then v = 1.
If x = 1, y = 0, then v = 1.

// Now consider a top-level that uses two G submodules and two H submodules. The first input of all four submodules is connect to input 'x', and the second input of all four submodules is connected to 'y'. The output of the first G submodule is connected to a two-input AND, along with the output of the first H submodule. The second pair of G and H submodules is similarly connected to an XOR gate. The output of the AND and the XOR is connected to a NOR, whose output is 'v'.

// Implement this circuit in Verilog.

module top_module(
    input x,
    input y,
    output v);

code:
module G(
    input x,
    input y,
    output v
);
    assign v = ~(x & y);
endmodule

module H(
    input x,
    input y,
    output v
);
    assign v = ~(x & y);
endmodule

module top_module(
    input x,
    input y,
    output v
);
    wire g1_out, g2_out, h1_out, h2_out;
    wire and_out, xor_out;

    G g1(.x(x), .y(y), .v(g1_out));
    G g2(.x(x), .y(y), .v(g2_out));
    H h1(.x(x), .y(y), .v(h1_out));
    H h2(.x(x), .y(y), .v(h2_out));

    assign and_out = g1_out & h1_out;
    assign xor_out = g2_out ^ h2_out;

    assign v = ~(and_out | xor_out);
endmodule

