module sequence_detector (
    input clk,
    input in,
    input reset,
    output match);parameter S0=0, S1=1, S10=2, S101=3, S1010=4;
    reg [2:0] state;
    reg [2:0] next;

    always_comb begin
        case (state)
            S0: next = in ? S1 : S0;
            S1: next = in ? S0 : S10;
            S10: next = in ? S101 : S0;
            S101: next = in ? S0 : S1010;
            S1010: next = in ? S1 : S0;
        endcase
    end

    always @(posedge clk) begin
        if (reset) state <= S0;
        else state <= next;
    end

    assign match = (state == S1010);

endmodule

