module top_module(
    input clk,
    input reset,          // Synchronous active-high reset
    output [3:0] counter_output,
    input [1:0] input_sel,
    output reg [3:0] output_sel
);reg [3:0] count;

always @(posedge clk) begin
    if (reset) begin
        count <= 4'b0000;
    end else begin
        count <= count + 1;
    end
end

assign counter_output = count;

always @(*) begin
    case ({input_sel, count})
        {2'b00, 4'b0000}: output_sel = 4'b0000;
        {2'b00, 4'b0001}, {2'b00, 4'b0010}, {2'b00, 4'b0011}: output_sel = 4'b0001;
        {2'b00, 4'b0100}, {2'b00, 4'b0101}, {2'b00, 4'b0110}, {2'b00, 4'b0111}: output_sel = 4'b0010;
        {2'b01, 4'b0000}: output_sel = 4'b0011;
        {2'b01, 4'b0001}, {2'b01, 4'b0010}, {2'b01, 4'b0011}: output_sel = 4'b0100;
        {2'b01, 4'b0100}, {2'b01, 4'b0101}, {2'b01, 4'b0110}, {2'b01, 4'b0111}: output_sel = 4'b0101;
        {2'b10, 4'b0000}: output_sel = 4'b0110;
        {2'b10, 4'b0001}, {2'b10, 4'b0010}, {2'b10, 4'b0011}: output_sel = 4'b0111;
        {2'b10, 4'b0100}, {2'b10, 4'b0101}, {2'b10, 4'b0110}, {2'b10, 4'b0111}: output_sel = 4'b1000;
        {2'b11, 4'b0000}: output_sel = 4'b1001;
        {2'b11, 4'b0001}, {2'b11, 4'b0010}, {2'b11, 4'b0011}: output_sel = 4'b1010;
        {2'b11, 4'b0100}, {2'b11, 4'b0101}, {2'b11, 4'b0110}, {2'b11, 4'b0111}: output_sel = 4'b1011;
        default: output_sel = 4'b0000;
    endcase
end

endmodule

