module traffic_light_system (
	input clk,
	input resetn,
	output reg red,
	output reg yellow,
	output reg green);

	parameter RED=0, YELLOW=1, GREEN=2;
	reg [1:0] state, next_state;

	always @(posedge clk) begin
		if (~resetn) state <= RED;
		else state <= next_state;
	end

	always_comb begin
		case (state)
			RED: next_state = GREEN;
			GREEN: next_state = YELLOW;
			YELLOW: next_state = RED;
			default: next_state = RED;
		endcase
	end

	always @(state) begin
		case (state)
			RED: begin
				red = 1;
				yellow = 0;
				green = 0;
			end
			YELLOW: begin
				red = 0;
				yellow = 1;
				green = 0;
			end
			GREEN: begin
				red = 0;
				yellow = 0;
				green = 1;
			end
			default: begin
				red = 1;
				yellow = 0;
				green = 0;
			end
		endcase
	end
endmodule

